<div id="users" class="section hidden">
 <div class="mb-6"><h1 class="text-3xl font-bold">کاربران</h1><p class="mt-1 text-gray-500">تعیین نقش‌ها و مجوزهای اختصاصی هر کاربر</p></div>
 <div class="mb-5 grid gap-3 rounded-3xl bg-white p-4 shadow-sm md:grid-cols-3"><input id="accessUserSearch" oninput="searchAccessUsers()" class="rounded-xl border px-4 py-3" placeholder="جستجو در نام، نام کاربری، موبایل یا ایمیل..."><select id="accessUserBranch" onchange="loadAccessUsers(1)" class="rounded-xl border px-4"><option value="">همه شعبه‌ها</option></select><select id="accessUserStatus" onchange="loadAccessUsers(1)" class="rounded-xl border px-4"><option value="">همه وضعیت‌ها</option><option value="pending">در انتظار</option><option value="approved">تأییدشده</option><option value="rejected">ردشده</option><option value="inactive">غیرفعال</option><option value="banned">مسدود</option></select></div>
 <div class="overflow-hidden rounded-3xl bg-white shadow"><div class="overflow-x-auto"><table class="w-full min-w-[1000px]"><thead class="bg-gray-50"><tr><th class="p-5 text-right">کاربر</th><th class="p-5 text-right">نقش‌ها</th><th class="p-5 text-right">مجوزهای اختصاصی</th><th class="p-5 text-right">وضعیت</th><th class="p-5"></th></tr></thead><tbody id="accessUsersBody" class="divide-y text-sm"></tbody></table></div><div class="flex flex-wrap items-center justify-between gap-3 border-t p-4"><div class="flex items-center gap-3"><span id="accessUsersInfo" class="text-sm text-gray-500"></span><select id="accessUsersPerPage" onchange="changeAccessUsersPerPage(this.value)" class="rounded-xl border px-3 py-2"><option>10</option><option selected>20</option><option>30</option><option>50</option><option>100</option></select></div><div id="accessUsersPagination" class="flex gap-2"></div></div></div>
</div>
